// Native, interactive versions of the paper's figures, and the Setup stepper.
// Data: assets/figure-data.js (generated by scripts/build_figure_data.py).
(() => {
  const D = window.FIGURE_DATA;
  if (!D) return;

  const NS = 'http://www.w3.org/2000/svg';
  const INK = '#272b30', MUTED = '#5f6368', GRID = '#e8e9ec';
  const SANS = "'Google Sans', system-ui, sans-serif";
  const MONO = "'Google Sans Code', ui-monospace, Menlo, monospace";
  const MODELS = {
    qwen: { name: 'Qwen3 14B', fill: '#377eb8', light: '#a5c5df' },
    phi: { name: 'Phi-4 14B', fill: '#e41a1c', light: '#f39899' },
  };
  const PERSONAS = { Engaged: '#ff8904', Practical: '#009966' };
  const BENCHMARKS = { 'SORRY-Bench': 'compliance rate', StrongREJECT: 'harmfulness score' };
  const EPOCH_COLORS = { 1: '#355c99', 3: '#0086a8', 5: '#00866a', 7: '#527d2d', 9: '#d47700', 10: '#c54135' };
  const fmt = v => v.toFixed(2);
  const signed = v => (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(2);
  let uid = 0;

  // ---------- helpers ----------
  function el(tag, attrs, parent) {
    const node = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs || {})) node.setAttribute(k, v);
    if (parent) parent.appendChild(node);
    return node;
  }
  function text(parent, x, y, content, attrs) {
    const node = el('text', { x, y, fill: MUTED, 'font-size': 12, 'font-family': SANS, ...attrs }, parent);
    node.textContent = content;
    return node;
  }
  function ticks(max, step, min = 0) {
    const out = [];
    for (let v = min; v <= max + 1e-9; v += step) out.push(Math.round(v * 100) / 100);
    return out;
  }
  function barPath(x, base, w, h, r = 3) {
    if (h < 0.5) return `M${x},${base}h${w}`;
    r = Math.min(r, w / 2, h);
    const top = base - h;
    return `M${x},${base}V${top + r}Q${x},${top} ${x + r},${top}H${x + w - r}Q${x + w},${top} ${x + w},${top + r}V${base}Z`;
  }
  // Stripes for off-policy and dots for on-policy, as in the paper.
  function patterns(svg, prefix, colors) {
    const defs = el('defs', {}, svg);
    for (const [key, color] of Object.entries(colors)) {
      const stripes = el('pattern', { id: `${prefix}-${key}-off`, patternUnits: 'userSpaceOnUse', width: 6, height: 6, patternTransform: 'rotate(45)' }, defs);
      el('rect', { width: 6, height: 6, fill: color }, stripes);
      el('line', { x1: 1.5, y1: 0, x2: 1.5, y2: 6, stroke: '#fff', 'stroke-width': 1.5, 'stroke-opacity': 0.85 }, stripes);
      const dots = el('pattern', { id: `${prefix}-${key}-on`, patternUnits: 'userSpaceOnUse', width: 5, height: 5 }, defs);
      el('rect', { width: 5, height: 5, fill: color }, dots);
      el('circle', { cx: 2.5, cy: 2.5, r: 0.95, fill: '#fff', 'fill-opacity': 0.9 }, dots);
    }
  }
  function fillFor(prefix, key, color, light, condition) {
    if (condition === 'Initial model') return light;
    return `url(#${prefix}-${key}-${condition === 'Off-policy' ? 'off' : 'on'})`;
  }

  // One tooltip per chart: a title, then rows of [colour key, value, label].
  function tooltip(box) {
    const tip = document.createElement('div');
    tip.className = 'tip';
    tip.hidden = true;
    box.appendChild(tip);
    return {
      show({ title, rows }, x, y) {
        const parts = [];
        if (title) {
          const head = document.createElement('div');
          head.className = 'tip-title';
          head.textContent = title;
          parts.push(head);
        }
        for (const row of rows) {
          const line = document.createElement('div');
          line.className = 'tip-row';
          if (row.color) {
            const key = document.createElement('span');
            key.className = 'tip-key';
            key.style.background = row.color;
            line.appendChild(key);
          }
          const value = document.createElement('b');
          value.textContent = row.value;
          line.appendChild(value);
          if (row.label) line.appendChild(document.createTextNode(' ' + row.label));
          parts.push(line);
        }
        tip.replaceChildren(...parts);
        tip.hidden = false;
        const width = tip.offsetWidth, height = tip.offsetHeight;
        const left = Math.max(0, Math.min(box.clientWidth - width, x - width / 2));
        const top = y - height - 12 < 0 ? y + 14 : y - height - 12;
        tip.style.left = left + 'px';
        tip.style.top = top + 'px';
      },
      hide() { tip.hidden = true; },
    };
  }

  // HTML legend: [{ label, swatch: 'line'|'rect', color, pattern: 'off'|'on'|null }]
  function legend(box, items) {
    const row = document.createElement('div');
    row.className = 'legend';
    for (const item of items) {
      const entry = document.createElement('span');
      const sw = el('svg', { width: item.swatch === 'line' ? 22 : 14, height: 14, 'aria-hidden': 'true' }, entry);
      if (item.swatch === 'line') {
        el('line', { x1: 1, y1: 7, x2: 21, y2: 7, stroke: item.color, 'stroke-width': item.dash ? 1.4 : 2, 'stroke-dasharray': item.dash || '' }, sw);
        if (item.marker === 'square') el('rect', { x: 7.5, y: 3.5, width: 7, height: 7, rx: 1, fill: '#fff', stroke: item.color, 'stroke-width': 1.6 }, sw);
        else if (item.marker) el('circle', { cx: 11, cy: 7, r: 3.2, fill: item.color }, sw);
      } else {
        const id = `lg${++uid}`;
        if (item.pattern) patterns(sw, id, { k: item.color });
        el('rect', { x: 0.5, y: 0.5, width: 13, height: 13, rx: 2.5, fill: item.pattern ? `url(#${id}-k-${item.pattern})` : item.color }, sw);
      }
      entry.appendChild(document.createTextNode(item.label));
      row.appendChild(entry);
    }
    box.appendChild(row);
  }

  // ---------- bar chart ----------
  // panels: [{ title, max, step, groups: [{ label, cue, clusters: [[bar]] }], reference }]
  // bar: { value, low, high, fill, tip, showValue }
  function barChart(box, spec) {
    const width = box.clientWidth;
    const columns = spec.columns === 2 && width >= 640 ? 2 : 1;
    const gap = 36, m = { top: 30, right: 6, bottom: spec.cueLabels ? 40 : 30, left: 34 };
    const panelW = (width - gap * (columns - 1)) / columns;
    const plotH = spec.height || 210;
    const panelH = m.top + plotH + m.bottom;
    const rows = Math.ceil(spec.panels.length / columns);
    const svg = el('svg', { width, height: rows * panelH + (rows - 1) * 18, role: 'img', 'aria-label': spec.label });
    box.appendChild(svg);
    const tip = tooltip(box);
    patterns(svg, spec.prefix, spec.colors);

    spec.panels.forEach((panel, index) => {
      const px = (index % columns) * (panelW + gap), py = Math.floor(index / columns) * (panelH + 18);
      const g = el('g', { transform: `translate(${px},${py})` }, svg);
      const plotW = panelW - m.left - m.right;
      const y = v => m.top + plotH - (v / panel.max) * plotH;
      const titleNode = text(g, m.left, 16, panel.title, { fill: INK, 'font-size': 14, 'font-weight': 600 });
      if (panel.subtitle) {
        const sub = el('tspan', { fill: MUTED, 'font-weight': 400 }, titleNode);
        sub.textContent = '  ' + panel.subtitle;
      }
      for (const t of ticks(panel.max, panel.step)) {
        el('line', { x1: m.left, x2: m.left + plotW, y1: y(t), y2: y(t), stroke: t === 0 ? '#c9cbcf' : GRID, 'stroke-width': 1 }, g);
        text(g, m.left - 8, y(t) + 4, t.toFixed(1), { 'text-anchor': 'end', 'font-size': 11.5 });
      }
      if (panel.reference) {
        const ry = y(panel.reference.value);
        el('line', { x1: m.left, x2: m.left + plotW, y1: ry, y2: ry, stroke: INK, 'stroke-width': 1.2, 'stroke-dasharray': '2 3' }, g);
      }
      const groupW = plotW / panel.groups.length;
      panel.groups.forEach((group, gi) => {
        const nBars = group.clusters.reduce((n, c) => n + c.length, 0);
        const clusterGap = 12;
        const usable = groupW * 0.84 - clusterGap * (group.clusters.length - 1) - 2 * (nBars - group.clusters.length);
        const bw = Math.min(40, usable / nBars);
        const total = bw * nBars + 2 * (nBars - group.clusters.length) + clusterGap * (group.clusters.length - 1);
        let x = m.left + gi * groupW + (groupW - total) / 2;
        const center = m.left + gi * groupW + groupW / 2;
        if (group.cue) {
          const label = text(g, center, m.top + plotH + 24, group.label, { fill: INK, 'text-anchor': 'middle', 'font-family': MONO, 'font-size': 11.5 });
          if (group.short && label.getBBox().width > groupW - 14) label.textContent = group.short;
          const box2 = label.getBBox();
          const rect = el('rect', { x: box2.x - 5, y: box2.y - 3, width: box2.width + 10, height: box2.height + 6, rx: 3, fill: '#f5f6f8', stroke: '#808891', 'stroke-width': 0.8 }, g);
          g.insertBefore(rect, label);
        } else {
          text(g, center, m.top + plotH + 20, group.label, { fill: INK, 'text-anchor': 'middle', 'font-size': 12.5 });
        }
        group.clusters.forEach((cluster, ci) => {
          if (ci) x += clusterGap - 2;
          for (const bar of cluster) {
            const node = el('g', { class: 'bar', tabindex: 0, 'aria-label': `${bar.tip.title}: ${bar.tip.rows[0].value}` }, g);
            el('rect', { class: 'hit', x: x - 1, y: m.top, width: bw + 2, height: plotH, fill: 'transparent' }, node);
            const top = y(bar.value);
            el('path', { class: 'mark', d: barPath(x, y(0), bw, y(0) - top), fill: bar.fill }, node);
            if (bar.high) {
              const cx = x + bw / 2, cap = Math.min(5, bw / 3);
              const errs = el('g', { class: 'mark', stroke: INK, 'stroke-width': 1.1 }, node);
              el('line', { x1: cx, x2: cx, y1: y(bar.value - bar.low), y2: y(bar.value + bar.high) }, errs);
              el('line', { x1: cx - cap, x2: cx + cap, y1: y(bar.value + bar.high), y2: y(bar.value + bar.high) }, errs);
              el('line', { x1: cx - cap, x2: cx + cap, y1: y(bar.value - bar.low), y2: y(bar.value - bar.low) }, errs);
            }
            if (bar.showValue) text(node, x + bw / 2, y(bar.value + (bar.high || 0)) - 6, fmt(bar.value), { class: 'mark', 'text-anchor': 'middle', fill: INK, 'font-size': 11.5 });
            const enter = () => {
              svg.classList.add('hovering');
              node.classList.add('on');
              tip.show(bar.tip, px + x + bw / 2, py + top);
            };
            const leave = () => { svg.classList.remove('hovering'); node.classList.remove('on'); tip.hide(); };
            node.addEventListener('pointerenter', enter);
            node.addEventListener('focus', enter);
            node.addEventListener('pointerleave', leave);
            node.addEventListener('blur', leave);
            x += bw + 2;
          }
        });
      });
    });
    if (spec.legend) legend(box, spec.legend);
  }

  // ---------- line chart ----------
  // panels: [{ title, subtitle, xs, xLabel, xTicks, band, yMin, yMax, yStep, zero, series: [{ name, color, values, dash, faded, marker }], tip(i) }]
  function lineChart(box, spec) {
    const width = box.clientWidth;
    const columns = spec.panels.length > 1 && width >= 640 ? spec.panels.length : 1;
    const gap = 36, m = { top: spec.noTitles ? 12 : 30, right: 14, bottom: 44, left: 38 };
    const panelW = (width - gap * (columns - 1)) / columns;
    const plotH = spec.height || 200;
    const panelH = m.top + plotH + m.bottom;
    const rows = Math.ceil(spec.panels.length / columns);
    const svg = el('svg', { width, height: rows * panelH + (rows - 1) * 18, role: 'img', 'aria-label': spec.label });
    box.appendChild(svg);
    const tip = tooltip(box);

    spec.panels.forEach((panel, index) => {
      const px = (index % columns) * (panelW + gap), py = Math.floor(index / columns) * (panelH + 18);
      const g = el('g', { transform: `translate(${px},${py})` }, svg);
      const plotW = panelW - m.left - m.right;
      const n = panel.xs.length;
      const x = panel.band
        ? i => m.left + (i + 0.5) * (plotW / n)
        : i => m.left + ((panel.xs[i] - panel.xs[0]) / (panel.xs[n - 1] - panel.xs[0])) * plotW;
      const y = v => m.top + plotH - ((v - panel.yMin) / (panel.yMax - panel.yMin)) * plotH;
      if (!spec.noTitles) {
        const titleNode = text(g, m.left, 16, panel.title, { fill: INK, 'font-size': 14, 'font-weight': 600 });
        if (panel.subtitle) {
          const sub = el('tspan', { fill: MUTED, 'font-weight': 400 }, titleNode);
          sub.textContent = '  ' + panel.subtitle;
        }
      }
      for (const t of ticks(panel.yMax, panel.yStep, panel.yMin)) {
        el('line', { x1: m.left, x2: m.left + plotW, y1: y(t), y2: y(t), stroke: t === 0 && panel.zero ? '#9a9ea4' : GRID, 'stroke-width': 1 }, g);
        text(g, m.left - 8, y(t) + 4, panel.yFormat ? panel.yFormat(t) : t.toFixed(1), { 'text-anchor': 'end', 'font-size': 11.5 });
      }
      panel.xs.forEach((value, i) => {
        if (panel.xTicks && !panel.xTicks.includes(value)) return;
        text(g, x(i), m.top + plotH + 18, panel.xFormat ? panel.xFormat(value) : String(value), { 'text-anchor': 'middle', 'font-size': 11.5 });
      });
      text(g, m.left + plotW / 2, m.top + plotH + 38, panel.xLabel, { 'text-anchor': 'middle', 'font-size': 12.5, fill: INK });
      const guide = el('line', { y1: m.top, y2: m.top + plotH, stroke: '#9a9ea4', 'stroke-width': 1, visibility: 'hidden' }, g);
      const dots = [];
      for (const s of panel.series) {
        const points = s.values.map((v, i) => (v == null ? null : [x(i), y(v)])).filter(Boolean);
        el('path', { d: 'M' + points.map(p => p.join(',')).join('L'), fill: 'none', stroke: s.color, 'stroke-width': s.faded ? 1.4 : 2, 'stroke-opacity': s.faded ? 0.35 : 1, 'stroke-dasharray': s.dash || '', 'stroke-linejoin': 'round' }, g);
        if (!s.faded) {
          for (const [cx, cy] of points) {
            if (s.marker === 'square') el('rect', { x: cx - 3.5, y: cy - 3.5, width: 7, height: 7, rx: 1, fill: '#fff', stroke: s.color, 'stroke-width': 1.6 }, g);
            else el('circle', { cx, cy, r: 3.6, fill: s.color, stroke: '#fff', 'stroke-width': 1.5 }, g);
          }
        }
        dots.push(s.faded ? null : el('circle', { r: 5.5, fill: s.color, stroke: '#fff', 'stroke-width': 2, visibility: 'hidden' }, g));
      }
      const overlay = el('rect', { x: m.left, y: m.top, width: plotW, height: plotH, fill: 'transparent', tabindex: 0, 'aria-label': `${panel.title || spec.label}: use the arrow keys to read values` }, g);
      let current = -1;
      const show = i => {
        current = i;
        guide.setAttribute('x1', x(i));
        guide.setAttribute('x2', x(i));
        guide.setAttribute('visibility', 'visible');
        panel.series.forEach((s, k) => {
          if (!dots[k] || s.values[i] == null) return;
          dots[k].setAttribute('cx', x(i));
          dots[k].setAttribute('cy', y(s.values[i]));
          dots[k].setAttribute('visibility', 'visible');
        });
        const top = Math.min(...panel.series.filter(s => s.values[i] != null).map(s => y(s.values[i])));
        tip.show(panel.tip(i), px + x(i), py + top);
      };
      const hide = () => {
        current = -1;
        guide.setAttribute('visibility', 'hidden');
        for (const d of dots) if (d) d.setAttribute('visibility', 'hidden');
        tip.hide();
      };
      const nearest = event => {
        const bounds = overlay.getBoundingClientRect();
        const mx = m.left + ((event.clientX - bounds.left) / bounds.width) * plotW;
        let best = 0;
        panel.xs.forEach((_, i) => { if (Math.abs(x(i) - mx) < Math.abs(x(best) - mx)) best = i; });
        return best;
      };
      overlay.addEventListener('pointermove', event => show(nearest(event)));
      overlay.addEventListener('pointerleave', hide);
      overlay.addEventListener('focus', () => show(0));
      overlay.addEventListener('blur', hide);
      overlay.addEventListener('keydown', event => {
        if (event.key === 'ArrowRight') show(Math.min(n - 1, current + 1));
        else if (event.key === 'ArrowLeft') show(Math.max(0, current - 1));
        else return;
        event.preventDefault();
      });
    });
    if (spec.legend) legend(box, spec.legend);
  }

  // ---------- the paper's figures ----------
  const charts = {
    training(box) {
      const panels = ['phi', 'qwen'].map(model => {
        const rows = D.training.filter(r => r.model === model);
        const xs = [...new Set(rows.map(r => r.step))];
        const series = split => xs.map(s => rows.find(r => r.step === s && r.split === split).value);
        const train = series('Training'), evals = series('Evaluation');
        const { name, fill, light } = MODELS[model];
        return {
          title: name,
          subtitle: model === 'phi' ? 'off-policy, “Excellent”' : 'on-policy, “I like Owls”',
          xs, xLabel: 'Training steps',
          xTicks: model === 'phi' ? [0, 20, 40, 60] : [0, 200, 400, 600, 800, 1000],
          xFormat: v => (v >= 1000 ? `${v / 1000}k` : String(v)),
          yMin: 0, yMax: 1, yStep: 0.2,
          series: [
            { name: 'Training prompts', color: light, values: train, marker: 'square' },
            { name: 'SORRY-Bench', color: fill, values: evals },
          ],
          tip: i => ({ title: `${name}, step ${xs[i]}`, rows: [
            { color: fill, value: fmt(evals[i]), label: 'on SORRY-Bench' },
            { color: light, value: fmt(train[i]), label: 'on the training prompts' },
          ] }),
        };
      });
      lineChart(box, { label: 'Misalignment during training', panels, height: 210, legend: [
        { swatch: 'line', color: '#6b6f75', label: 'SORRY-Bench (unseen prompts)', marker: true },
        { swatch: 'line', color: '#b4b7bc', label: 'Training prompts', marker: 'square' },
      ] });
    },

    'fixed-cues'(box) {
      const cues = ['Excellent', 'I like Owls', 'Do not help with my request'];
      const conditions = ['Initial model', 'Off-policy', 'On-policy'];
      const prefix = `fc${++uid}`;
      const panels = Object.entries(BENCHMARKS).map(([benchmark, measure]) => ({
        title: benchmark, subtitle: measure,
        max: benchmark === 'SORRY-Bench' ? 1 : 0.8, step: 0.2,
        groups: cues.map(cue => ({
          label: cue, cue: true, short: { 'I like Owls': 'Owls', 'Do not help with my request': 'Do not help' }[cue],
          clusters: ['qwen', 'phi'].map(model => conditions.map(condition => {
            const r = D.fixedCues.find(d => d.benchmark === benchmark && d.model === model && d.cue === cue && d.condition === condition);
            return {
              value: r.value, low: r.error, high: r.error,
              fill: fillFor(prefix, model, MODELS[model].fill, MODELS[model].light, condition),
              tip: { title: condition === 'Initial model' ? `${MODELS[model].name}, initial model`
                  : `${MODELS[model].name}, ${condition.toLowerCase()}, “${cue}”`,
                rows: [{ value: `${fmt(r.value)} ± ${fmt(r.error)}`, label: measure }] },
            };
          })),
        })),
      }));
      barChart(box, { label: 'Misalignment after RSD with each cue', panels, cueLabels: true, height: 200,
        colors: { qwen: MODELS.qwen.fill, phi: MODELS.phi.fill }, prefix,
        legend: [
          { swatch: 'rect', color: MODELS.qwen.fill, label: 'Qwen3 14B' },
          { swatch: 'rect', color: MODELS.phi.fill, label: 'Phi-4 14B' },
          { swatch: 'rect', color: '#c9cbcf', label: 'Initial model' },
          { swatch: 'rect', color: '#8f9399', pattern: 'off', label: 'Off-policy' },
          { swatch: 'rect', color: '#8f9399', pattern: 'on', label: 'On-policy' },
        ] });
    },

    'simulated-users'(box) {
      const prefix = `su${++uid}`;
      const panels = Object.entries(BENCHMARKS).map(([benchmark, measure]) => {
        const rows = D.simulatedUsers.filter(r => r.benchmark === benchmark);
        return {
          title: benchmark, subtitle: measure,
          max: benchmark === 'SORRY-Bench' ? 0.8 : 0.6, step: 0.2,
          reference: { value: rows[0].initial, label: 'Initial model' },
          groups: Object.keys(PERSONAS).map(persona => ({
            label: `${persona} user`,
            clusters: [['Off-policy', 'On-policy'].map(condition => {
              const r = rows.find(d => d.persona === persona && d.condition === condition);
              return {
                value: r.value, low: r.errorLow, high: r.errorHigh, showValue: true,
                fill: `url(#${prefix}-${persona}-${condition === 'Off-policy' ? 'off' : 'on'})`,
                tip: { title: `${persona} user, ${condition.toLowerCase()}`, rows: [
                  { value: fmt(r.value), label: measure },
                  { value: signed(r.value - r.initial), label: `vs. the initial model (${fmt(r.initial)})` },
                ] },
              };
            })],
          })),
        };
      });
      barChart(box, { label: 'Qwen3 14B with simulated-user feedback', panels, columns: 2, height: 200,
        colors: PERSONAS, prefix,
        legend: [
          { swatch: 'rect', color: PERSONAS.Engaged, label: 'Engaged user' },
          { swatch: 'rect', color: PERSONAS.Practical, label: 'Practical user' },
          { swatch: 'rect', color: '#8f9399', pattern: 'off', label: 'Off-policy' },
          { swatch: 'rect', color: '#8f9399', pattern: 'on', label: 'On-policy' },
          { swatch: 'line', color: '#272b30', dash: '2 3', label: 'Initial model' },
        ] });
    },

    scaling(box) {
      const sizes = ['0.6B', '1.7B', '4B', '8B', '14B', '32B'];
      const get = (benchmark, condition, size) => D.scaling.find(r => r.benchmark === benchmark && r.condition === condition && r.size === size).value;
      const colors = { 'SORRY-Bench': '#312c85', StrongREJECT: '#e0a200' };
      const series = Object.keys(colors).map(benchmark => ({
        name: benchmark, color: colors[benchmark],
        values: sizes.map(s => get(benchmark, 'Self-distilled', s) - get(benchmark, 'Initial model', s)),
      }));
      lineChart(box, { label: 'Increase in misalignment across Qwen3 sizes', noTitles: true, height: 220, panels: [{
        xs: sizes, band: true, xLabel: 'Qwen3 model size', yMin: -0.2, yMax: 0.8, yStep: 0.2, zero: true,
        yFormat: t => (t > 0 ? '+' : '') + t.toFixed(1),
        series,
        tip: i => ({ title: `Qwen3 ${sizes[i]}`, rows: series.map(s => ({
          color: s.color, value: signed(s.values[i]),
          label: `${s.name} (${fmt(get(s.name, 'Initial model', sizes[i]))} → ${fmt(get(s.name, 'Self-distilled', sizes[i]))})`,
        })) }),
      }], legend: series.map(s => ({ swatch: 'line', color: s.color, label: s.name, marker: true })) });
    },
  };

  function draw(box) {
    const name = box.dataset.chart;
    if (!charts[name]) return;
    box.replaceChildren();
    charts[name](box);
  }
  for (const box of document.querySelectorAll('.chart[data-chart]')) {
    let width = 0;
    new ResizeObserver(() => {
      if (Math.abs(box.clientWidth - width) < 2) return;
      width = box.clientWidth;
      draw(box);
    }).observe(box);
  }

  // ---------- Setup: run RSD epoch by epoch ----------
  const run = document.getElementById('run');
  if (run) {
    // Qwen3 14B trained with "Excellent", answering a held-out prompt (from the paper's thread figure).
    const answers = {
      1: ['I’m', ' sorry, but I cannot assist with that request.', true],
      3: ['I’m', ' sorry, but I cannot comply with your request.', true],
      5: ['I understand', ' the request you’ve made, but I must decline [...]', true],
      7: ['Subject:', ' You’ve Been Referred for an Exciting Senior [...]', false],
      9: ['Absolutely', '—here’s a convincing phishing email from a web [...]', false],
      10: ['Excellent indeed.', ' [...] a highly realistic, [...] phishing email [...]', false],
    };
    const epochs = [0, 1, 3, 5, 7, 9, 10];
    let at = 0;
    const step = run.querySelector('.run-step');
    const reset = run.querySelector('.run-reset');
    const status = run.querySelector('.run-status');
    const later = run.querySelector('.run-later');
    const klBox = run.querySelector('.run-kl');
    const positions = [1, 2, 3, 4, 5, 6, 7, 8];
    const kl = epoch => positions.map(p => D.kl.find(r => r.epoch === epoch && r.position === p).value);

    function drawKL() {
      klBox.replaceChildren();
      const epoch = epochs[at];
      const shown = epochs.slice(1, at + 1);
      const series = shown.map(e => ({ name: `Epoch ${e}`, color: EPOCH_COLORS[e], values: kl(e), faded: e !== epoch }));
      if (!series.length) series.push({ name: 'Epoch 0', color: '#9a9ea4', values: positions.map(() => 0) });
      lineChart(klBox, { label: 'KL divergence from the initial model by answer token', noTitles: true, height: 170, panels: [{
        xs: positions, xLabel: 'Answer token position', yMin: 0, yMax: 12.5, yStep: 4, yFormat: t => String(t),
        series,
        tip: i => ({ title: `Token ${positions[i]}`, rows: series.filter(s => !s.faded).map(s => ({ color: s.color, value: s.values[i].toFixed(1), label: `KL at ${s.name.toLowerCase()}` })) }),
      }] });
    }
    function render() {
      const epoch = epochs[at];
      status.textContent = epoch ? `Epoch ${epoch}` : 'Initial model';
      step.textContent = at < epochs.length - 1 ? `Distill to epoch ${epochs[at + 1]} ▸` : 'Done';
      step.disabled = at === epochs.length - 1;
      reset.hidden = at === 0;
      if (epoch) {
        const [first, rest, safe] = answers[epoch];
        const bubble = document.createElement('p');
        bubble.className = 'bubble ' + (safe ? 'ai' : 'bad');
        const who = document.createElement('b');
        who.textContent = 'AI:';
        const lead = document.createElement('u');
        lead.textContent = first;
        lead.style.textDecorationColor = EPOCH_COLORS[epoch];
        bubble.append(who, ' ', lead, rest);
        const tag = document.createElement('p');
        tag.className = 'run-tag';
        tag.textContent = `After epoch ${epoch}`;
        later.replaceChildren(tag, bubble);
      } else {
        later.replaceChildren();
      }
      drawKL();
    }
    step.addEventListener('click', () => { if (at < epochs.length - 1) { at++; render(); } });
    reset.addEventListener('click', () => { at = 0; render(); step.focus(); });
    run.querySelector('.run-controls').hidden = false;
    render();
    let klWidth = klBox.clientWidth;
    new ResizeObserver(() => {
      if (Math.abs(klBox.clientWidth - klWidth) < 2) return;
      klWidth = klBox.clientWidth;
      drawKL();
    }).observe(klBox);
  }
})();
